'use client';

/**
 * Video Intake Admin Page
 * 
 * Form to submit a YouTube URL for processing through the intake pipeline.
 * Shows real-time processing status and results.
 * 
 * Route: /admin/intake
 */

import { useState } from 'react';

// ─── Types ───────────────────────────────────────────────────────────────────

interface IntakeStep {
    name: string;
    status: 'pending' | 'running' | 'success' | 'skipped' | 'failed';
    message?: string;
    duration_ms?: number;
}

interface IntakeResult {
    status: string;
    videoId: string;
    title?: string;
    classification?: {
        is_profound: boolean;
        experience_type: string;
        confidence: number;
        justification: string;
        isNde_value: string;
    } | null;
    analysisSummary?: string;
    error?: string;
    steps: IntakeStep[];
}

// ─── Status Styling ──────────────────────────────────────────────────────────

const statusIcons: Record<string, string> = {
    pending: '⏳',
    running: '🔄',
    success: '✅',
    skipped: '⏭️',
    failed: '❌',
};

const resultBadge: Record<string, { label: string; className: string }> = {
    complete: { label: 'Processed Successfully', className: 'bg-green-900/30 text-green-300 border-green-700' },
    already_exists: { label: 'Already in Database', className: 'bg-amber-900/30 text-amber-300 border-amber-700' },
    not_profound: { label: 'Not a Profound Experience', className: 'bg-red-900/30 text-red-300 border-red-700' },
    no_captions: { label: 'No Captions Available', className: 'bg-yellow-900/30 text-yellow-300 border-yellow-700' },
    failed: { label: 'Processing Failed', className: 'bg-red-900/30 text-red-300 border-red-700' },
};

// ─── Component ───────────────────────────────────────────────────────────────

export default function IntakePage() {
    const [url, setUrl] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [result, setResult] = useState<IntakeResult | null>(null);
    const [error, setError] = useState<string | null>(null);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!url.trim() || isLoading) return;

        setIsLoading(true);
        setResult(null);
        setError(null);

        try {
            const response = await fetch('/api/intake', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ url: url.trim() }),
            });

            const data = await response.json();

            if (!response.ok && !data.steps) {
                setError(data.error || 'Unknown error');
            } else {
                setResult(data);
            }
        } catch (err: any) {
            setError(err.message || 'Network error');
        } finally {
            setIsLoading(false);
        }
    };

    const badge = result ? resultBadge[result.status] : null;

    return (
        <div className="min-h-screen bg-gray-950 text-gray-100">
            <div className="max-w-3xl mx-auto px-4 py-12">
                {/* Header */}
                <div className="mb-8">
                    <h1 className="text-3xl font-bold text-white mb-2">Video Intake Pipeline</h1>
                    <p className="text-gray-400">
                        Submit a YouTube URL to scrape, classify, and analyze a potential NDE video.
                    </p>
                </div>

                {/* URL Form */}
                <form onSubmit={handleSubmit} className="mb-8">
                    <div className="flex gap-3">
                        <input
                            type="text"
                            value={url}
                            onChange={(e) => setUrl(e.target.value)}
                            placeholder="https://www.youtube.com/watch?v=..."
                            className="flex-1 px-4 py-3 bg-gray-900 border border-gray-700 rounded-lg text-white placeholder-gray-500 focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 transition-colors"
                            disabled={isLoading}
                        />
                        <button
                            type="submit"
                            disabled={isLoading || !url.trim()}
                            className="px-6 py-3 bg-blue-600 text-white rounded-lg font-medium hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed transition-colors whitespace-nowrap"
                        >
                            {isLoading ? (
                                <span className="flex items-center gap-2">
                                    <svg className="animate-spin h-4 w-4" viewBox="0 0 24 24">
                                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none" />
                                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
                                    </svg>
                                    Processing...
                                </span>
                            ) : (
                                'Process Video'
                            )}
                        </button>
                    </div>
                    <p className="mt-2 text-sm text-gray-500">
                        Supports youtube.com, youtu.be, and YouTube Shorts URLs
                    </p>
                </form>

                {/* Error Display */}
                {error && (
                    <div className="mb-6 p-4 bg-red-900/20 border border-red-800 rounded-lg">
                        <p className="text-red-300 font-medium">Error</p>
                        <p className="text-red-400 text-sm mt-1">{error}</p>
                    </div>
                )}

                {/* Results */}
                {result && (
                    <div className="space-y-6">
                        {/* Result Badge */}
                        {badge && (
                            <div className={`p-4 border rounded-lg ${badge.className}`}>
                                <div className="flex items-center justify-between">
                                    <div>
                                        <p className="font-semibold text-lg">{badge.label}</p>
                                        {result.title && (
                                            <p className="text-sm opacity-80 mt-1">{result.title}</p>
                                        )}
                                    </div>
                                    {result.videoId && (result.status === 'complete' || result.status === 'already_exists') && (
                                        <a
                                            href={`/video/${result.videoId}`}
                                            className="text-sm underline opacity-70 hover:opacity-100"
                                        >
                                            See Video and Analysis →
                                        </a>
                                    )}
                                </div>
                                {result.classification && (
                                    <div className="mt-3 pt-3 border-t border-current/20">
                                        <div className="grid grid-cols-3 gap-4 text-sm">
                                            <div>
                                                <span className="opacity-60">Type:</span>{' '}
                                                <span className="font-medium">{result.classification.experience_type.toUpperCase()}</span>
                                            </div>
                                            <div>
                                                <span className="opacity-60">Confidence:</span>{' '}
                                                <span className="font-medium">{result.classification.confidence}%</span>
                                            </div>
                                            <div>
                                                <span className="opacity-60">Classification:</span>{' '}
                                                <span className="font-medium">{result.classification.isNde_value}</span>
                                            </div>
                                        </div>
                                        {result.classification.justification && (
                                            <p className="mt-2 text-sm opacity-70 italic">
                                                &ldquo;{result.classification.justification}&rdquo;
                                            </p>
                                        )}
                                    </div>
                                )}
                                {result.analysisSummary && (
                                    <p className="mt-3 text-sm opacity-80">{result.analysisSummary}</p>
                                )}
                            </div>
                        )}

                        {/* Processing Steps */}
                        {result.steps.length > 0 && (
                            <div className="bg-gray-900/50 border border-gray-800 rounded-lg p-4">
                                <h3 className="text-sm font-medium text-gray-400 mb-3 uppercase tracking-wider">
                                    Processing Steps
                                </h3>
                                <div className="space-y-2">
                                    {result.steps.map((step, i) => (
                                        <div
                                            key={i}
                                            className="flex items-start gap-3 py-1.5 text-sm"
                                        >
                                            <span className="text-base mt-0.5 shrink-0">
                                                {statusIcons[step.status] || '•'}
                                            </span>
                                            <div className="min-w-0 flex-1">
                                                <span className={`font-medium ${step.status === 'failed' ? 'text-red-400'
                                                    : step.status === 'success' ? 'text-green-400'
                                                        : step.status === 'skipped' ? 'text-gray-500'
                                                            : 'text-gray-300'
                                                    }`}>
                                                    {step.name}
                                                </span>
                                                {step.message && (
                                                    <span className="text-gray-500 ml-2">— {step.message}</span>
                                                )}
                                            </div>
                                            {step.duration_ms !== undefined && (
                                                <span className="text-gray-600 text-xs shrink-0">
                                                    {step.duration_ms < 1000
                                                        ? `${step.duration_ms}ms`
                                                        : `${(step.duration_ms / 1000).toFixed(1)}s`
                                                    }
                                                </span>
                                            )}
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        {/* Quick Links */}
                        {result.status === 'complete' && result.videoId && (
                            <div className="flex gap-3 text-sm">
                                <a
                                    href={`/video/${result.videoId}`}
                                    className="px-4 py-2 bg-blue-600/20 text-blue-300 border border-blue-700 rounded-lg hover:bg-blue-600/30 transition-colors"
                                >
                                    View on Site →
                                </a>
                                <button
                                    onClick={() => {
                                        setUrl('');
                                        setResult(null);
                                    }}
                                    className="px-4 py-2 bg-gray-800 text-gray-300 border border-gray-700 rounded-lg hover:bg-gray-700 transition-colors"
                                >
                                    Process Another
                                </button>
                            </div>
                        )}
                    </div>
                )}

                {/* Loading State */}
                {isLoading && !result && (
                    <div className="text-center py-12">
                        <div className="animate-spin h-8 w-8 border-2 border-blue-500 border-t-transparent rounded-full mx-auto mb-4" />
                        <p className="text-gray-400">Processing video through the intake pipeline...</p>
                        <p className="text-gray-500 text-sm mt-1">This typically takes 30-60 seconds</p>
                    </div>
                )}
            </div>
        </div>
    );
}
